<!doctype html><html><head><meta charset="utf-8"><title>Medical Archives API Test</title><style>body{font:16px Arial;max-width:800px;margin:40px auto;padding:0 18px;color:#173d34}button{padding:10px 16px;background:#08756e;color:white;border:0;border-radius:8px;cursor:pointer}pre{background:#f1f7f4;padding:16px;border-radius:10px;white-space:pre-wrap}</style></head><body><h1>Medical Archives API Test</h1><p>Checks PHP and MySQL connection.</p><button onclick="check()">Test Connection</button><pre id="result">Not tested yet.</pre><script>async function check(){let e=document.getElementById('result');try{let r=await fetch('api/health',{credentials:'same-origin'});e.textContent=JSON.stringify(await r.json(),null,2)}catch(x){e.textContent=x.message}}</script></body></html>